function getSourceId(sender, callback, request) {
  var presetSources = ["screen", "window", "tab"];
  var sourcesToUse = request.sources || presetSources;

  var tab = sender.tab;

  // https://bugs.chromium.org/p/chromium/issues/detail?id=425344
  tab.url = sender.url;

  // Gets chrome media stream token and returns it in the response.
  chrome.desktopCapture.chooseDesktopMedia(
    sourcesToUse, tab,
    function (streamId) {
      if (!streamId || !streamId.length) {
        callback({ error: 'permissionDenied' });
        return;
      }

      callback({ streamId: streamId });
    });

  return true;
}

chrome.runtime.onMessageExternal.addListener(
  function(request, sender, callback) {
    console.log("RECEIVED REQUEST " + JSON.stringify(request, null, 2));
    if(request.getVersion) {
      callback({ version: chrome.runtime.getManifest().version });
      return false;
    } else if(request.getStream) {
      getSourceId(sender, callback, request);
      return true;
    } else {
      callback({ error: 'malformed request', request });
      return false;
    }
  }
);

/*
 * Title: Basic Node app example
 * Description: Simple node application that print random quotes per second interval.
 * Author: Sumit Saha ( Learn with Sumit )
 * Date: 11/09/19
 *
 */

// Dependencies
var mathLibrary = require('./lib/math');
var quotesLibrary = require('./lib/quotes');

// App object - Module scaffolding
var app = {};

// Configuration
app.config = {
    timeBetweenQuotes: 1000,
};

// Function that prints a random quote
app.printAQuote = function printAQuote() {
    // Get all the quotes
    var allQuotes = quotesLibrary.allQuotes();

    // Get the length of the quotes
    var numberOfQuotes = allQuotes.length;

    // Pick a random number between 1 and the number of quotes
    var randomNumber = mathLibrary.getRandomNumber(1, numberOfQuotes);

    // Get the quote at that position in the array (minus one)
    var selectedQuote = allQuotes[randomNumber - 1];

    // Print the quote to the console
    console.log(selectedQuote);
};

// Function that loops indefinitely, calling the printAQuote function as it goes
app.indefiniteLoop = function indefiniteLoop() {
    // Create the interval, using the config variable defined above
    setInterval(app.printAQuote, app.config.timeBetweenQuotes);
};

// Invoke the loop
app.indefiniteLoop();

