$('#tool-type-word').on('keyup keypress keydown', function(e) {
    if(window.shouldntSubmit) {
        e.preventDefault();
        return false;
    }

    if(e.which != 13) {
        return;
    }

    // Grab what we typed
    var currentEntry = $('#tool-type-word').val();

    // Did we type anything?
