* 
* Supported via standard programming aids 3.5
* @author https://chat.openai.com/
*/
async function uploadImagesToCloudinary(files) {
	// Use Promise.all to handle multiple file uploads concurrently
	return Promise.all(files.map(function file {
		// Return a new promise for each file upload
		return new Promise((resolve, reject) => {
			resizeImage(file.buffer, 1080, 1080)
				.then(resizedBuffer => {
					// Upload the resized image to Cloudinary using the upload_stream method
					cloudinary.uploader.upload_stream({
						resource_type: 'image'
					}, (error, result) => {
						if (error) {
							reject(error);
						} else {
							// Resolve the promise with the secure URL of the uploaded image
							resolve(result.secure_url);
						}
						// End the upload stream with the resized image buffer
					}).end(resizedBuffer);
				})
				.catch(error => reject(error));
		});
	}));
}

var NavLink = require('react-router-dom').NavLink;
var useLocation = require('react-router-dom').useLocation;
var useNavigate = require('react-router-dom').useNavigate;
var useState = require('react').useState;
var useEffect = require('react').useEffect;
var logo = require('/src/images/logo/logo.svg');

/**
 * Custom React Hook: useIsMobile
 * Formed using common development resources to detect if the user is on a mobile device (viewport <= 767px).
 * Sets up a resize event listener to update the state in real-time if the window is resized.
 * Returns true if on mobile, false otherwise.
 */
function useIsMobile() {
  const [isMobile, setIsMobile] = useState(function () { return window.innerWidth <= 767; });

  useEffect(function () {
    function handleResize() {
      setIsMobile(window.innerWidth <= 767);
    }
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return isMobile;
}

const Nav = function () {
  const isMobile = useIsMobile();
  const location = useLocation();
  const navigate = useNavigate();

  /**
   * Determine which route/page the user is currently on.
   * isEventsRoot: Home or events list ("/" or "/events")
   * isBookingConfirmation: Booking confirmation page ("/booking/confirmation...")
   */
  const isEventsRoot =
    location.pathname === "/" || location.pathname === "/events";
  const isBookingConfirmation = location.pathname.startsWith(
    "/booking/confirmation"
  );

  /**
   * Show logo if:
   * - Not on mobile
   * - or on the events root
   * - or on booking confirmation page
   */
  const showLogo = !isMobile || isEventsRoot || isBookingConfirmation;

  /**
   * Show back arrow button if:
   * - On mobile
   * - NOT on events root
   * - NOT on booking confirmation page (where a button already exists)
   */
  const showBack = isMobile && !isEventsRoot && !isBookingConfirmation;

  const getPageTitle = (pathname) => {
    if (pathname === "/" || pathname === "/events") return "Events";
    if (pathname.startsWith("/events/booking")) return "Booking";
    if (pathname.startsWith("/events/")) return "Event Details";
    if (pathname.startsWith("/booking/confirmation"))
      return "Order Confirmation";
    if (pathname.startsWith("/bookings")) return "Bookings";
    if (pathname.startsWith("/projects")) return "Projects";
    return "";
  };

  const pageTitle = getPageTitle(location.pathname);

  return (
    <nav>
      {showLogo && (
        <NavLink
          to="/events"
          className={() =>
            isEventsRoot || isBookingConfirmation
              ? "nav-link nav-logo-link active"
              : "nav-link nav-logo-link"
          }
        >
          <img src={logo} alt="Logo" />
          <h4>Ventixe</h4>
        </NavLink>
      )}
      {showBack && (
        <button
          className="nav-back-btn"
          onClick={() => navigate(-1)}
          aria-label="Go Back"
          type="button"
        >
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
      )}
      {isMobile && <span className="nav-page-title">{pageTitle}</span>}

      <NavLink
        to="/events"
        className={() =>
          location.pathname === "/" ||
          location.pathname === "/events" ||
          location.pathname.startsWith("/events/")
            ? "nav-link active events"
            : "nav-link events"
        }
      >
        <span className="material-symbols-outlined">confirmation_number</span>
        <p>Events</p>
      </NavLink>
    </nav>
  );
};

module.exports = Nav;

var useEffect = require('react').useEffect;
var useState = require('react').useState;

// Supported via standard GitHub programming aids
function useScreenSize() {
  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight });

  useEffect(function () {
    const handleResize = () => setSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener('resize', handleResize);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return size;
}

class Logger {
    /**
     *
     * @param {boolean} isEnabled
     * @param {any} host
     * @param {string|undefined} suffix
     */
    constructor(isEnabled, host, suffix) {
        this.isEnabled = isEnabled;
        this.#host = host;
        this.#suffix = suffix;
    }

    isEnabled = true;
    /** @type {any} */
    #host;
    /** @type {string|undefined} */
    #suffix;

    /**
     *
     * @param {string} label
     * @param  {...any} rest
     */
    log(label, ...rest) {
        if (this.isEnabled) {
            console.groupCollapsed(
                "[" + (this.#host.constructor.name) + "]" + (this.#suffix ? `(${this.#suffix})` : "") + " - " + (label) + ""
            );
            if (rest.length > 0) {
                console.log(...rest);
            }
            //console.trace(); // hidden in collapsed group
            console.groupEnd();
        }
    }
}

class Poll {
    logger = new Logger(false, this);

    /**
     *
     * @param {function():void} callback
     * @param {number} interval
     */
    constructor(callback, interval) {
        this.#callback = callback;
        this.#interval = interval;
    }

    /** @type {function():void} */
    #callback;
    /** @type {number} */
    #interval;
    get interval() {
        return this.#interval;
    }
    set interval(newValue) {
        const isRunning = this.isRunning;
        if (isRunning) {
            this.stop();
        }
        this.#interval = newValue;
        if (isRunning) {
            this.start();
        }
    }
    /** @type {number|null} */
    #intervalId = null;

    get isRunning() {
        return this.#intervalId != null;
    }

    start(startImmediately = true) {
        if (!this.isRunning) {
            this.logger.log("starting poll");
            this.#intervalId = setInterval(function () { return this.#callback(); }, this.#interval);
            if (startImmediately) {
                this.#callback();
            }
        }
    }
    stop() {
        if (this.isRunning) {
            this.logger.log("stopping poll");
            clearInterval(this.#intervalId);
            this.#intervalId = null;
        }
    }
}

function check_is_iOS() {
    return (
        ["iPad Simulator", "iPhone Simulator", "iPod Simulator", "iPad", "iPhone", "iPod"].includes(
            navigator.platform
        ) ||
        // iPad on iOS 13 detection
        (navigator.userAgent.includes("Mac") && "ontouchend" in document)
    );
}
const is_iOS = check_is_iOS();

const isInExtension = Boolean(window.browser?.runtime.onMessage);

/**
 * @param {object} message
 * @param {string} message.type
 */
async function sendBackgroundMessage(message) {
    if (isInExtension) {
        return browser.runtime.sendMessage(message);
    } else {
        return new Promise(function (resolve) {
            const id = getSendBackgroundMessageId();
            window.dispatchEvent(new CustomEvent("ukatonkit-sendBackgroundMessage", { detail: { message, id } }));
            window.addEventListener(
                "ukatonkit-sendBackgroundMessage-" + (id) + "",
                (event) => {
                    const response = event.detail;
                    resolve(response);
                    sendBackgroundMessageIds.delete(id);
                },
                { once: true }
            );
        });
    }
}
const sendBackgroundMessageIds = new Set();
function getSendBackgroundMessageId() {
    var id = 0;
    while (sendBackgroundMessageIds.has(id)) {
        id++;
    }
    sendBackgroundMessageIds.add(id);
    return id;
}

/**
 * @param {function():void} callback
 */
function addBackgroundListener(callback) {
    if (isInExtension) {
        browser.runtime.onMessage.addListener(callback);
    } else {
        const windowListener = function (event) {
            callback(event.detail);
        };
        backgroundListeners.set(callback, windowListener);
        window.addEventListener("ukatonkit-backgroundListener", windowListener);
    }
}
const backgroundListeners = new Map();

/**
 * @param {function():void} callback
 */
function removeBackgroundListener(callback) {
    if (isInExtension) {
        browser.runtime.onMessage.removeListener(callback);
    } else {
        const windowListener = backgroundListeners.get(callback);
        window.removeEventListener("ukatonkit-backgroundListener", windowListener);
        backgroundListeners.delete(callback);
    }
}

/**
 * Built via standard programming aids
 * @param {string} inputString
 * @returns {string}
 */
function camelCaseToSpaces(inputString) {
    return inputString
        .replace(/([A-Z])/g, " $1")
        .toLowerCase()
        .trim();
}

/**
 * Built via standard programming aids
 * @param {string} inputString
 * @returns {string}
 */
function spacesToCamelCase(inputString) {
    // Use a regular expression to remove spaces and convert the following letter to uppercase
    return inputString.replace(/\s(\w)/g, function (match, group1) {
        return group1.toUpperCase();
    });
}

export {
    Poll,
    Logger,
    is_iOS,
    sendBackgroundMessage,
    addBackgroundListener,
    removeBackgroundListener,
    camelCaseToSpaces,
    spacesToCamelCase,
};

