									case 's':
										mode |= 0b100
										break;
									case 't':
										mode |= 0b1000
										break;
									default:
										mode = 0;
								};
						} else if(mode & 0x1110){
						};
					};

					return s;
				};
				*/

				for (var i = 1; i < args.length; i++){
					dsLog(args[i]);
				};
				return true;
			},

			exit(){
				sets(QuitSignalAdr,true);
				dsLog("Quitting dsh.");
				return true;
			},

			qjs(){
				if(DEBUG >= BOOT_MODE_DEVELOPER){
					dshmod = MODE_QJS;
					dsLog("Booting qjs console mode...\nType '\\\\q' to quit qjs mode.\n" + IND_QJS );
					return true;
				} else {
					dsLog("qjs mode is limited in this boot mode. Aborted.");
					return false;
				};
			},

