	/**
	 * Cmd.map
	 * namespace for Commands that affect RTS game map.
	 * RTSマップに干渉するタイプのコマンド集
	 * @namespace Cmd.map
	 */
	map: {
		CmdType: CTYP_MAP,


		/* spawnerInfoUpdate: ()=> {
			if (Cmd.bl_SpawnCmdCalled == false){}
		} need to consider well */ 

		// {int}, array[x,y]

		/**
		 * Spawns an unit as a agent to given pos in RTS map.
		 *
		 * @param {trpid} troopid
		 * @param {[int,int]} tilepos
