		/**
		 * Spawns group of agents on map.
		 * And returns {RTSagentGroup}
		 *
		 * @param {string} troopid - "TRP_brabra". may work with int but highly recommend using stringid.
		 * @param {[int,int]} tilepos - 
		 * @param {int} team - 
