		 * @param {int} amount - 
		 * @param {int} dir -
		 * @param {int} stance - 
		 * @param {} flag
		 * @return {RTSagentGroup} -
		 */
		spawnAgentgroup: function(troopid,tilepos,team,delta,amount,dir,stance,flag){
			// temp
			troopid = trpid.convert(troopid);
			var pos = tilepos;
			var agentslist = [];
			for (var i = 0; i < amount; i++){ // this one is too slow 
				agentslist[i] = this.spawnAgent(troopid,pos,team,dir,stance,flag);
				for (var p = 0; p < 2; p++){pos[p] += delta[p];}; // add delta
			};
			var expected_agentgroup = new RTSagentGroup(agentslist,team);
			return expected_agentgroup;
