	// -------------
	// Cmd.group
	// -------------

	group: { 
		CmdType: CTYP_GROUP,
		cgrp: [], // agentid array
		Adr_cgrp_list_head: getv(1212),

		// @param {RTSagentGroup} grp You can hand agentid array as well.
		setCgrp: function(grp){
			var agentlist = "";
			if (Array.isArray(grp)){
				for (var elm of grp) {
					agentlist += elm + "|";
				};
			} else { 
				for (var elm of grp.getids()) {
					agentlist += elm + "|";
				};
			};
			// deblog(agentlist)
			Cmd.Qset(this.CmdType,"stCgrp",agentlist);
			this.cgrp = grp;
		},

		checkCurrentGroup: function(grp){
			if(grp == 0) { // if 0 is given, return current selecting group
				grp = this.cgrp;
			} else {
				if(grp != this.cgrp){
					this.setCgrp(grp);
				};
			};
			return grp;
		},

		registerCohort: function(grp,player,cohortid) {
			this.checkCurrentGroup(grp);

			// temporary only for player
			if (player == 0){
				Cmd.Qset(this.CmdType,"regiCoh","" + (player) + "," + (cohortid) + "," + (this.Adr_cgrp_list_head) + "," + (grp.idlist.length) + "");
			};
			return new DIS_cohort(player,cohortid,grp.idlist);
		},


		/**
		 * Simplest way to order agents to move.
		 *
		 * @param {agent_idlist} grp
		 * @param {array} path
		 * @param {int} attackmove
		 * @param {int} formationType - 0:free, 1:line
		 * @param {} fl = 0x2 - You don't need to set this unless you know what you're gonna do. 
		 *           0x1:attack move, 0x2:use pathfinding, 0x4:just change direction, 0x8: formation direction manually set
		 *
		 * @param {int} angle = -1 - You can set angle manually in range of 0~360000. 
		 *           If you give a number below 0, this argument means nothing
		 */
		moveToPoint: function(grp,path,attackmove = 0,formType = 0,fl = 0x2,angle = -1){
			grp = this.checkCurrentGroup(grp);
			var goal = path; // kari
			fl |= attackmove;
			fl |= angle > 0 ? 0x8 : 0;

			Cmd.Qset(this.CmdType,"agtmv","" + (goal[0]) + "," + (goal[1]) + "," + (fl) + "," + (formType) + "");
		},

		/**
		 * Order given agent grp to advance straightly to the designated point. 
		 * With this command, agents don't try pathfinding.
		 *
		 * @param {} grp
		 * @param {} path
		 * @param {} attackmove
		 */
		advanceToPoint: function(grp,pt,attackmove = 1){
			this.moveToPoint(grp,pt,attackmove,1,0);
		},

		turnForPoint: function(grp,pt,formType = 1){
			this.moveToPoint(grp,pt,1,formType,0x4);
		},

		attack: function(grp,targetid){
			grp = this.checkCurrentGroup(grp);
			Cmd.Qset(this.CmdType,"atk","" + (targetid) + "");
		},

		/**
		 * .
		 *
		 * @param {} grp
		 * @param {int} stanceid - 0:,
		 * @param {} fl
		 */
		setStance: function(grp,stanceid,fl = 0){
			grp = this.checkCurrentGroup(grp);
			Cmd.Qset(this.CmdType,"setSt","" + (stanceid) + "," + (fl) + "");
		},

	},


	/**
	 * Radio Dialogs and etc etc
	 * @namespace Cmd.ui
	 */
		ui: {
			CmdType: CTYP_UI,

	/**
	 * Sends very simple dialog to Radio dialog manager.
	 * Returns nothing.
	 *
	 * @param {string} txt
	 * @param {int} time
	 * @param {} face
	 */
			sendSimpleDialog: function(txt,time,face){
				var log = new DIS_dialog(txt,time,face);
				_pushDialogQueue(log);
			},

			/**
			 * Send push Dialog queue command to RPG maker.
			 * Called by other methods in Cmd.ui
			 *
			 * @param {} dlog
			 */
			_pushDialogQueue: function(dlog){ // push arg to dialog queue and toggle dialog manager switch
				// set up string

				var sendstring = (DIS.string.convertString(dlog.string) + "," + dlog.showframe + "," + make_Array_DIStable(dlog.icon) + "," + make_Array_DIStable(dlog.size) + "," + make_Array_DIStable(dlog.opensound) + ";");

				Cmd.Qset(this.CmdType,"pushDialogQueue",sendstring);
				RTS.DlogManager.afterEffects.push(dlog.afterEffect);
				// deblog(sendstring);
			},

			forceSkipDialog: function(skipi){ // toggle break flag switch
				Cmd.Qset(this.CmdType,"forceSkipDialog",skipi);
				// still triggers afterEffect()

			},

			clearDialogQueue: function(){ // init dialog queue and force break - clear event switch on
				RTS.DlogManager.afterEffects = []; // unlike forceSkip, thus will nullfy dialog afterEffect.
				Cmd.Qset(this.CmdType,"clearDialogQueue","");

			},

			// UNDERCONSTRUCTION
			sendRMDialog: function(txt,face){
				var log = new DIS_RMDialog(txt,face);
				_pushDialogQueue(log); 
			},

			getPictureInfo: function(picid){
				var rei = Cmd.ReturnQueue.length // return index
				Cmd.Qset(this.CmdType,"getPictureInfo","" + (picid) + "," + (rei) + "");
				var retLink = new CmdRetLink(RMarray)
				return retLink;
			},



	},

	/**
	 * This has similar functions with Cmd.map,
	 * but methods in this object tend to deal with more complicated classes
	 * @namespace Cmd.obj
	 */
	obj: (function(){
		// CmdType as a private const is better. Other objects in Cmd will also be refactored in this way.
		var CmdType = CTYP_OBJ;

		return {

			/**
			 * Simillar to Cmd.map.spawnAgent(), but uses DIS_unit as param.
			 *
			 * @param {DIS_unit} unit - DO NOT USE trpid here, you need to prepare DIS_unit type object.
			 * @param {[int,int]} tilepos - [x,y]
			 * @param {int} team - 
			 * @param {int} dir - 
			 * @param {int} stance - 
			 * @param {} flag
			 * @return {DIS_agent}
			 */
			placeUnitAsAgent: function(unit,tilepos,team,dir,stance,flag){
				// UNCO
				var troopid = 0; // get from DIS_unit
				dir = dir || Cmd.runFlags.spawnagent_lastdir;
				stance = stance || 0;
				flag = flag || 0;

				Cmd.Qset(CmdType,"plcAg","" + (troopid) + "," + (tilepos[0]) + "," + (tilepos[1]) + "," + (team) + "," + (dir) + "," + (stance) + "");
				var protoagent = new DIS_agent(DIS.agent.searchEmptySpace(),troopid,team,false);

				/*
				 copy EX events from given DIS_unit
				 */

				Cmd.runFlags.spawnagent_lastdir = dir
				return protoagent;
			},
		};

	})(),



};


