// Bilinear picture size changing functions.
// NEED REORGANIZATION
// basically Drafted using standard development resources so you need to fix these anyway
// TODO: calc as float and round into int just before pushing into array.
function linearInterpolate(color1, color2, factor) {
	var a1 = (color1 >> 24) & 0xff;
	var r1 = (color1 >> 16) & 0xff;
	var g1 = (color1 >> 8) & 0xff;
	var b1 = color1 & 0xff;

	var a2 = (color2 >> 24) & 0xff;
	var r2 = (color2 >> 16) & 0xff;
	var g2 = (color2 >> 8) & 0xff;
	var b2 = color2 & 0xff;

	var r = Math.round(r1 + factor * (r2 - r1));
	var g = Math.round(g1 + factor * (g2 - g1));
	var b = Math.round(b1 + factor * (b2 - b1));
	var a = 0xff // Math.round(a1 + factor * (a2 - a1)); // With current 2003MP, you need not to consider about alpha channel

	return (a << 24) | (r << 16) | (g << 8) | b;
}

function getPixel(imageData, width, height, x, y) {
	if (x < 0 || x >= width || y < 0 || y >= height) {
		return 0; // If the pixel is out of picture, just return 0. 範囲外の場合は黒（または透明）を返す
	}
	return imageData[y * width + x];
}

function resizeImage(imageData, originalWidth, originalHeight,rate) {
	var newWidth = originalWidth * rate;
	var newHeight = originalHeight * rate;
	var resizedData = [];

	for (var y = 0; y < newHeight; y++) {
		for (var x = 0; x < newWidth; x++) {
			var srcX = (x / newWidth) * originalWidth;
			var srcY = (y / newHeight) * originalHeight;

			var x0 = Math.floor(srcX);
			var x1 = Math.min(Math.ceil(srcX), originalWidth - 1);
			var y0 = Math.floor(srcY);
			var y1 = Math.min(Math.ceil(srcY), originalHeight - 1);

			var factorX = srcX - x0;
			var factorY = srcY - y0;

			var p1 = getPixel(imageData, originalWidth, originalHeight, x0, y0);
			var p2 = getPixel(imageData, originalWidth, originalHeight, x1, y0);
			var p3 = getPixel(imageData, originalWidth, originalHeight, x0, y1);
			var p4 = getPixel(imageData, originalWidth, originalHeight, x1, y1);

			var p12 = linearInterpolate(p1, p2, factorX);
			var p34 = linearInterpolate(p3, p4, factorX);
			var pFinal = linearInterpolate(p12, p34, factorY);

			resizedData[y * newWidth + x] = pFinal;
		};
	};
	return resizedData;
};

const readline = require('readline');
const fs = require('fs');
const path = require('path');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

const filePath = path.join(__dirname, 'data.json');

const data = {
  osuPath: '',
}

const localData = {
  mapsetId: 0,
  mapsetName: '',
  mapsetPath: '',
  mapsetFiles: [],
  mapsetBackground: '',
};

let backupId = Date.now() + Math.floor(Math.random() * 1000);

if (!fs.existsSync('backup')) {
  fs.mkdirSync('backup');
}

async function saveBackup() {
  fs.writeFileSync(path.join('backup', "backup-" + (backupId) + ".json"), JSON.stringify(localData));
}

// load data
if (fs.existsSync(filePath)) {
  const fileData = fs.readFileSync(filePath);
  Object.assign(data, JSON.parse(fileData));
}


if(data.osuPath === '') {
  rl.question('Enter your osu! path: ', function (answer) {
    data.osuPath = answer;
    fs.writeFileSync(filePath, JSON.stringify(data));
    console.log('osu! path saved');
  });
} else {
  rl.question("Load backup? Press enter if no, or enter the backup ID (excluding `backup-`, just the number.): ", function (answer) {
    if (answer !== "") {
      const backupFile = fs.readFileSync(path.join('backup', "backup-" + (answer) + ".json"));
      backupId = answer;
      Object.assign(localData, JSON.parse(backupFile));
      console.log('Backup loaded');
      loop();
    } else {
      loop();
    }
  });
}

async function loop() {

  if (localData.mapsetName === '') { // shouldn't be this if we loaded a backup!!
    rl.question("Choose a mapset name: ", function (answer) {
      localData.mapsetName = answer;
      localData.mapsetPath = path.join(data.osuPath, 'Songs', answer);
      saveBackup();
      newBeatmap();
    });
  } else {
    if (localData.mapsetFiles.length !== 0) {
      rl.question("You have loaded a backup. Do you want to add more beatmaps or build the map and exit? (y/n) ", function (answer) {
        if (answer === 'y') {
          newBeatmap();
          saveBackup();
        } else {
          console.log("Completed adding beatmaps to " + (localData.mapsetName) + "! Now creating the mapset folder.");
          saveBackup();
          createMapset();
          rl.close();
        }
      });
    } else {
      newBeatmap();
    }
  }

  function newBeatmap() {
    rl.question("Enter the beatmapset ID: (can be anything in your osu! songs folder: its the number at the start of the folder name - example: 93523 Tatsh - IMAGE -MATERIAL- Version 0) ", function (answer) {
      // beatmap-638553600109047587-… The sun, the moon, the stars

      let id = parseInt(answer);
      if (answer.startsWith('beatmap-')) {
        id = "beatmap-" + (answer.split('-')[1]) + "";
      }

      // console.log(id);
      // console.log(data.osuPath + "\\Songs");
      const folder = fs.readdirSync(data.osuPath + "\\Songs").find((file) => file.startsWith("" + (id) + ""));

      console.log(folder);

      if (!folder) {
        console.log('Beatmapset not found');
        return newBeatmap();
      }

      rl.question("Enter the beatmap diff: (must be inside the beatmapset folder you specified, and valid.) ", (answer) => {
        const mapsetFiles = fs.readdirSync(path.join(data.osuPath, 'Songs', folder));

        // console.log(mapsetFiles);
        const diff = mapsetFiles.find((file) => file.endsWith("[" + (answer) + "].osu"));
        const diffName = diff.split('[').pop().split(']').shift();

        if (!diff) {
          console.log('Beatmap diff not found');
          return newBeatmap();
        }

        rl.question("Enter the new diff name: ", (answer) => {
          const newDiff = answer;

          localData.mapsetFiles.push({
            id,
            folder,
            diff,
            diffName,
            newDiff
          });
          saveBackup();
          rl.question("Added beatmap. Add another? (y/n) ", (answer) => {
            if (answer === 'y') {
              newBeatmap();
            } else {
              console.log("Completed adding beatmaps to " + (localData.mapsetName) + "! Now creating the mapset folder.");
              saveBackup();
              createMapset();
              rl.close();
            }
          });
        });
      });
    });
  }
}

