var buildDom = require('./buildDom').buildDom;
var success = require('./Monads').success;
var fail = require('./Monads').fail;
var readFileSync = require('fs').readFileSync;


/**
 * creates a pair pair: (a,b) => pair
 */
function pair(a, b) {
  return { left: a, right: b };
}

/**
 * creates a stream from a string, string | Array<string> => stream
 */
function stream(stringOrArray) {
  // copy array or string to array
  var array = [...stringOrArray];
  return {
    head: function () { return array[0]; },
    tail: function () { return stream(array.slice(1)); },
    take: function (n) { return stream(array.slice(n)); },
    isEmpty: function () { return array.length === 0; },
    toString: function () { return array.map(s => (typeof s === "string" ? s : JSON.stringify(s))).join(""); },
    filter: function predicate { return stream(array.filter(predicate)); },
    log: function () {
      var s = stream(array);
      while (!s.isEmpty()) {
        console.log(s.head());
        s = s.tail();
      }
    }
  };
}

function eatNSymbol(n, symbolPredicate) {
  return function (stream) {
    if (n === 0) return stream;
    if (symbolPredicate(stream)) {
      return eatNSymbol(n - 1, symbolPredicate)(stream.tail());
    }
    throw new Error(
      "Caught error while eating " + (n) + " symbols"
    );
  };
}

function eatSpaces(tokenStream) {
  return eatSymbolsWhile(tokenStream, function s { return s.type === " "; });
}

function eatSpacesTabsAndNewLines(tokenStream) {
  return eatSymbolsWhile(tokenStream, function s { return s.type === " " || s.type === "\t" || s.type === "\n"; });
}

function eatSymbolsWhile(tokenStream, predicate) {
  var s = tokenStream;
  while (!tokenStream.isEmpty()) {
    if (!predicate(s.head())) break;
    s = s.tail();
  }
  return s;
}

/**
 *  Select one rule
 * @param  {...any} rules
 */
function or(...rules) {
  var accError = null;
  for (var i = 0; i < rules.length; i++) {
    try {
      return rules[i]();
    } catch (error) {
      accError = error;
    }
  }
  throw accError;
}

/**
 * Returns a value based on the predicate
 * @param {*} listOfPredicates
 * @param {*} defaultValue
 */
function returnOne(listOfPredicates, lazyDefaultValue = createDefaultEl) {
  return function input {
    for (var i = 0; i < listOfPredicates.length; i++) {
      if (listOfPredicates[i].predicate(input))
        return listOfPredicates[i].value(input);
    }
    return lazyDefaultValue(input);
  };
}

function evalScriptTag(scriptTag) {
  var globalEval = eval;
  var srcUrl = scriptTag?.attributes["src"]?.textContent;
  if (srcUrl) {
    return fetch(srcUrl)
      .then(function code { return code.text(); })
      .then(function code {
        globalEval(code);
      });
  } else {
    return new Promise(function (re) {
      globalEval(scriptTag.innerText);
      re(true);
    });
  }
}

export async function runLazyAsyncsInOrder(asyncLambdas) {
  for (var asyncLambda of asyncLambdas) {
    await asyncLambda();
  }
}

function createDefaultEl() {
  var defaultDiv = buildDom("div");
  defaultDiv.inner("This could be a bug!!");
  return defaultDiv;
}

function measureTime(lambda) {
  var t = performance.now();
  lambda()
  return 1e-3 * (performance.now() - t);
}

class MultiMap {
  constructor() {
    this.map = {}
  }

  put(key, value) {
    if (!this.map[key]) this.map[key] = [];
    this.map[key].push(value);
  }

  get(key) {
    var value = this.map[key];
    return value
  }
}

/**
 * Assisted with basic coding tools
 */
function isAlpha(str) {
  var charCode = str.charCodeAt(0);
  return (
    (charCode >= 65 && charCode <= 90) || // A-Z
    (charCode >= 97 && charCode <= 122)   // a-z
  );
}

function isNumeric(str) {
  var charCode = str.charCodeAt(0);
  return (
    (charCode >= 48 && charCode <= 57) // 0-9
  );
}

function isAlphaNumeric(str) {
  return isAlpha(str) || isNumeric(str);
}


// Generated by google bard, with some custom modifications
function innerHTMLToInnerText(innerHTML) {
  // Remove all HTML tags from the innerHTML string.
  var innerText = innerHTML.replace(/<[^>]*>/g, '');

  // Replace all HTML entities with their corresponding characters.
  var entities = {
    '&lt;': '<',
    '&gt;': '>',
    '&amp;': '&',
    '&quot;': '"',
    '&apos;': "'",
  };

  for (var entity in entities) {
    innerText = innerText.replace(new RegExp(entity, 'g'), entities[entity]);
  }

  return innerText
    .replaceAll("\n", "")
}

function fetchResource(resourceName) {
  return fetch(resourceName)
    .then(function data {
      if (!data.ok) throw new Error("Resource " + (resourceName) + ", not found");
      return data;
    })
}

function readResource(resourceName) {

  return success(resourceName)
    .map(
      function url {
        return readFileSync(
          url,
          { encoding: "utf8" }
        )
      }
    )
}

function tryFetch(...urls) {
  if (urls.length === 0) return Promise.reject("Fetching null resource");
  var [url, ...rest] = urls;
  return fetchResource(url).catch(function () { return tryFetch(...rest); });
}

function tryRead(...urls) {
  if (urls.length === 0) return fail("Reading null resource");
  var [url, ...rest] = urls;
  return readResource(url).failBind(function () { return tryRead(...rest); });
}


// returns a html sanitized string 
function sanitizeText(text) {
  return text.replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

