        `;
        document.body.appendChild(this.elem);*/

        this.fetch = this.clean('fetch');

        this.initiate();
    }

    Exploit.prototype.clean = function (key) {
        let iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        document.body.appendChild(iframe);

        let window = iframe.contentWindow;
        iframe.parentNode.removeChild(iframe);
        return window[key];
    };

    Exploit.prototype.closest_number = function (number = 0, array = []) {
        let arr = array.map(function (k) { return Math.abs(k - number) }),
            min = Math.min.apply(Math, arr);

        return array[arr.indexOf(min)];
    };

    Exploit.prototype.update_shop = function () {
        let upgrades = this.shop,
            money = this.money();

        document.querySelector('*[name="inp_mpq"]').textContent = '$' + this.closest_number(money, upgrades.MPQ);
        document.querySelector('*[name="inp_sb"]').textContent = '$' + this.closest_number(money, upgrades.SB);
        document.querySelector('*[name="inp_mp"]').textContent = '$' + this.closest_number(money, upgrades.Multi);
    };

    Exploit.prototype.money = function () {
        let root = document.getElementById('root'),
            money = root.children[0].children[0].textContent;

        return Number(money.replace(/[^0-9.-]+/g, ''))
    };

    Exploit.prototype.style_text = function (elem) {
        elem.style.borderRadius = '5px';
        elem.style.borderBottom = '5px solid red';
    };

    Exploit.prototype.style_img = function (elem) {
        elem.style.borderRadius = '5px';
        elem.style.borderBottom = '5px solid red';
    };

    Exploit.prototype.loop = function () {
        if (document.getElementsByClassName('animated tada').length || document.getElementsByClassName('animated jello').length) return false;

        let question = this.header().textContent,
            answers = this.terms.filter(e => e.text == question),
            answer = answers[Math.floor(Math.random() * answers.length)];

        if (!answer) return false;
        let type = answer.type

        answer = answer.answers.filter(e => e.correct)[0]

        if (type == 'mc') {
            if (answer.image) {
                let element = document.querySelector('img[src="' + (answer.image) + '"]');
                if (element) this.style_img(element);
            } else if (answer.text) {
                let elements = Array.from(document.querySelectorAll('span')).filter(e => e.textContent == answer.text),
                    element = elements[Math.floor(Math.random() * elements.length)];

                this.style_text(element);
            }
        } else if (type == 'text') {
            let input = this.input();
            if (input) {
                input.value = answer.text;
                input.placeholder = answer.text;
            }
        }
    };

    Exploit.prototype.initiate = function () {
        let questions = this.questions();
        if (questions.length < 1) return setTimeout(() => { this.initiate(); }, 1000);

        this.fetch_terms(questions[0].game, terms => {
            this.interval = setInterval(() => { this.loop(); }, 100);
        });
    };

    Exploit.prototype.fetch_terms = function (gameId = '', callback = console.log) {
        let req = new XMLHttpRequest();
        req.open('GET', 'https://www.gimkit.com/api/games/fetch/' + gameId);
        req.onreadystatechange = () => { 
            if (req.readyState == 4 && req.status == 200) {
                let json = JSON.parse(req.responseText);

                this.game = json;
                this.terms = json.kit.questions;

                if (callback) callback(json.kit.questions);
            }
        }
        req.send();
    };

    Exploit.prototype.questions = function () {
        let questions = JSON[Object.keys(JSON)[0]];
        return questions || [];
    }

    Exploit.prototype.header = function () {
        let root = document.getElementById('root');

        return root.children[0].children[1].children[0].children[0].children[0];
    };

    Exploit.prototype.options = function () {
        return Array.from(document.getElementById('root').children[0].children[1].children[0].children[0].children[1].children);
    };

    Exploit.prototype.input = function () {
        return document.querySelector('input');
    };

    alert('GIMKIT SCRIPT V0.02\n- Drew Snow\n\nThis script is "under development" as people are still complaining about being kicked.\n\nInstructions:\n‣ For text questions press any key inside the text box then click answer.\n‣ For multiple choice the correct answer should be underlined in red.\n\nThis script is still in beta, send me a message on discord if anything is not working correctly.');
    let Session = new Exploit();

    return 'Script has been loaded.';
})();

/**
 * @file            EvaluateHand.js
 * @description     This file contains a function that evaluates a poker hand and returns its rank.
 * @author          Johnathan Glasgow
 * @date            16/06/2024
 * @contributors    This code was largely Aided using common development resources
 */

/*
* This function takes a card string and returns its value.
* The value is a number from 2 to 14, where 11 represents a Jack, 12 a Queen, 13 a King, and 14 an Ace.
*
* @param {string} card - A two-character string representing a card.
* @returns {number} The value of the card.
*/
var getCardValue = function (card) {
    var value = card[0];
    switch (value) {
        case 'A': return 14;
        case 'K': return 13;
        case 'Q': return 12;
        case 'J': return 11;
        case 'T': return 10;
        default: return parseInt(value);
    }
}

/*
* This function evaluates a poker hand and returns its rank.
* The function takes an array of 5 cards, represented as strings.
* Each card string is a two-character string, where the first character represents the value of the card and the second character represents the suit.
* The function returns an object with two properties: rank and rankName.
* The rank property is a number from 1 to 10, representing the rank of the hand.
* The rankName property is a string representing the name of the rank.
* 
* @param {string[]} hand - An array of 5 cards, represented as strings.
* @returns {Object} An object with two properties: rank and rankName.
*/
var getHandRanking = function (hand) {
    var values = hand.map(card => getCardValue(card)).sort((a, b) => a - b);
    var suits = hand.map(card => card[1]);

    var isFlush = suits.every(suit => suit === suits[0]);

    var isStraight = values.every((val, index) => {
        if (index === 0) return true;
        return val === values[index - 1] + 1;
    });

    if (isFlush && values.join('') === '1011121314') return { rank: 10, rankName: 'Royal Flush' };
    if (isFlush && isStraight) return { rank: 9, rankName: 'Straight Flush' };
    if (values[0] === values[3] || values[1] === values[4]) return { rank: 8, rankName: 'Four of a Kind' };
    if ((values[0] === values[2] && values[3] === values[4]) || (values[0] === values[1] && values[2] === values[4])) return { rank: 7, rankName: 'Full House' };
    if (isFlush) return { rank: 6, rankName: 'Flush' };
    if (isStraight) return { rank: 5, rankName: 'Straight' };
    if (values[0] === values[2] || values[1] === values[3] || values[2] === values[4]) return { rank: 4, rankName: 'Three of a Kind' };
    if ((values[0] === values[1] && values[2] === values[3]) || (values[0] === values[1] && values[3] === values[4]) || (values[1] === values[2] && values[3] === values[4])) return { rank: 3, rankName: 'Two Pair' };
    if (values[0] === values[1] || values[1] === values[2] || values[2] === values[3] || values[3] === values[4]) return { rank: 2, rankName: 'One Pair' };

    return { rank: 1, rankName: 'No rank' };
}

var User = require('../models/user.js');
var jwt = require('jsonwebtoken');
var fs = require('fs');

/* Most of this codeblock was Assisted using common GitHub development aids :O */
// handle errors
const handleErrors = function (err) {
  const errors = {username: "", email: "", password: ""};
  if (err.code === 11000) {
    errors.username = "Username or email already taken";
    return errors; // return errors object
  }
  // if validation errors
  if (err.errors) {
    for (const field in err.errors) {
      errors[field] = err.errors[field].properties.message;
    }
  }
  return errors;
};
const maxAge = 7 * 24 * 60 * 60;
const createToken = function (id) {
  return jwt.sign({id}, process.env.JWT_SECRET, {
    expiresIn: maxAge,
  });
};

const createUser = async function (req, res) {
  var username = req.body.username;
var password = req.body.password;
var email = req.body.email;
  console.log(username, password, email);
  try {
    const user = await new User({
      username: username,
      password: password,
      email: email,
      fullname: username,
      profile_picture: "default.png",
      date_registered: new Date(),
    });
    await user.save();
    const token = createToken(user._id);
    res.cookie("jwt", token, {
      httpOnly: true,
      maxAge: maxAge * 1000,
    });
    res.status(201).send({user: user._id});
  } catch (err) {
    const errs = handleErrors(err);
    if (email == "") errs["email"] = "";
    res.status(400).send(errs);
  }
};

const editUser = async function (req, res) {
  var username = req.params.username;
  var fullname = req.body.fullname;
var email = req.body.email;
  try {
    const user = await User.findOne({username: username});

    if (!user) {
      return res.status(404).send({message: "User not found"});
    }

    await user.updateOne({
      fullname: (fullname != null ? fullname : user.fullname),
      email: (email != null ? email : user.email),
    });
    res.status(201).send({user: user._id});
  } catch (err) {
    res.status(400).send(err);
  }
};

const editUserPicture = async function (req, res) {
  var username = req.params.username;
  const picture = req.file;
  try {
    const user = await User.findOne({username: username});
    if (!user) {
      return res.status(404).send({message: "User not found"});
    }
    if (!picture) {
      return res.status(400).send({message: "No picture provided"});
    }
    const suffix = picture.originalname.split(".").pop();

    // First delete the old picture if it exists
    if (user.profile_picture && user.profile_picture !== "default.png") {
      fs.unlink(user.profile_picture, (err) => {
        if (err) console.error("Error deleting old picture:", err);
      });
    }

    await user.updateOne({
      profile_picture: "" + (picture.filename) + "_thumb." + (suffix) + ("" != null ? "" : "default.png"),
    });
    res.status(201).send({user: user._id});
  } catch (error) {
    console.error("Error updating user picture:", error);
    res.status(500).send({message: "Internal server error"});
  }
};

const login = async function (req, res) {
  var username = req.body.username;
var password = req.body.password;
  try {
    const user = await User.login(username, password);
    const token = createToken(user._id);
    res.cookie("jwt", token, {
      httpOnly: true,
      maxAge: maxAge * 1000,
    });
    res.status(200).send({user: user._id, token: token});
  } catch (err) {
    res.status(400).json({message: err.message});
  }
};

const logOut = function (req, res) {
  res.clearCookie("jwt", res.locals.user.token, {
    httpOnly: true,
    maxAge: maxAge * 1000,
  });
  res.status(200).send("Logged out");
};

const authorize = async function (req, res) {
  if (res.locals.user?.id) {
    const user = await User.findById(res.locals.user.id);
    await res.status(200).send({user: user});
  } else {
    res.status(401).send({message: "Unauthorized"});
  }
};

const findUserByName = async function (req, res) {
  var username = req.params.username;
  const user = await User.findOne({username: username});
  await res.status(200).send({user: user});
};

const addFavoriteRestaurant = async function (req, res) {
  const id = req.params.id;
  const user = await User.findById(res.locals.user.id);
  if (!user) {
    return res.status(404).send({message: "User not found"});
  }
  if (!user.favorite_restaurants.includes(id)) {
    user.favorite_restaurants.push(id);
    await user.save();
  }
  res
    .status(200)
    .send({message: "Restaurant added to favorites", status: "success"});
};

const removeFavoriteRestaurant = async function (req, res) {
  const id = req.params.id;
  const user = await User.findById(res.locals.user.id);
  if (!user) {
    return res.status(404).send({message: "User not found"});
  }
  if (user.favorite_restaurants.includes(id)) {
    user.favorite_restaurants = user.favorite_restaurants.filter(
      (restaurant) => restaurant !== id
    );
    await user.save();
  }
  res
    .status(200)
    .send({message: "Restaurant removed from favorites", status: "success"});
};

export {
  findUserByName,
  createUser,
  editUser,
  login,
  logOut,
  authorize,
  editUserPicture,
  addFavoriteRestaurant,
  removeFavoriteRestaurant,
};

var wall, thickness;
var bullet,speed, weight;

function setup() {
  createCanvas(1600, 400);

  speed=random(223,321)
  weight=random(30,52)


  thickness=random(22,83)





    bullet=createSprite(50, 200, 50,5);  
    bullet.velocityX = speed;
    bullet.shapeColor=color(255);




    wall=createSprite(1200, 200, thickness, height/2);  

    wall.shapeColor=color(230,230,230);
  //wall.shapeColor=color(80,80,80)
}


function draw() {
  background(0);  
  //bullet.sprite.collide(wall.sprite,calculateDeformation)
  if(hasCollided(bullet, wall))
  {
  	bullet.velocityX=0;
  	var damage=0.5 * weight * speed* speed/(thickness *thickness *thickness);


	if(damage>10)
	{
		wall.shapeColor=color(255,0,0);

	}



	if(damage<10)
	{
		wall.shapeColor=color(0,255,0);
	}

  }


  drawSprites();

}


function hasCollided(lbullet, lwall)
{
	bulletRightEdge=lbullet.x +lbullet.width;
	wallLeftEdge=lwall.x;
	if (bulletRightEdge>=wallLeftEdge)
	{
		return true
	}
	return false;
}

var _import = require('react');
var render = require('@testing-library/react').render;
var cleanup = require('@testing-library/react').cleanup;

var useAsyncTask = require('../src/index').useAsyncTask;
var useAsyncRun = require('../src/index').useAsyncRun;
var useAsyncTaskTimeout = require('../src/index').useAsyncTaskTimeout;

// FIXME we should fake timers
// jest.useFakeTimers();
const sleep = function (ms) { return new Promise((resolve) => setTimeout(resolve, ms)); };

describe('basic spec', function () {
  afterEach(cleanup);

  it('should have a function', () => {
    expect(useAsyncTask).toBeDefined();
  });

  it('should create a component with timeout', async () => {
    const Waiting = ({ abort }) => (
      <div>
        Waiting...
        <button type="button" onClick={abort}>Abort</button>
      </div>
    );
    const renderHi = () => <h1>Hi</h1>;
    const DelayedMessage = ({ delay }) => {
      const asyncTask = useAsyncTaskTimeout(renderHi, delay, [renderHi, delay]);
      useAsyncRun(asyncTask);
      var pending = asyncTask.pending;
var error = asyncTask.error;
var result = asyncTask.result;
var abort = asyncTask.abort;
      if (error) return <div>Error: {error.message}</div>;
      if (pending) return <Waiting abort={abort} />;
      return <div>Result: {result}</div>;
    };
    const App = () => (
      <StrictMode>
        <div>
          <DelayedMessage delay={300} />
          <DelayedMessage delay={100} />
        </div>
      </StrictMode>
    );
    var container = render.container;(<App />);
    expect(container).toMatchSnapshot();
    // jest.advanceTimersByTime(100);
    await sleep(100);
    expect(container).toMatchSnapshot();
    // jest.advanceTimersByTime(200);
    await sleep(200);
    expect(container).toMatchSnapshot();
  });
});

