function stringOfLength(string, length) {
    var newString = '';
    for (var i = 0; i < length; i++) {
      newString += string;
    }
    return newString;
  }

  function generateTitle(name) {
    var title = '`' + name + '` (component)';
    return title + '\n' + stringOfLength('=', title.length) + '\n';
  }

  function generateDesciption(description) {
    return description + '\n';
  }

  function generatePropType(type) {
    var values;
    var name;
    name = type.name;
    if(type.name==='signature'){
      name = type.raw;
    }
    if (Array.isArray(type.value)) {
      values =
        '(' +
        type.value
          .map(function(typeValue) {
            return typeValue.name || typeValue.value;
          })
          .join('|') +
        ')';
    } else {
      values = type.value;
    }

    return 'type: `' + name + (values ? values : '') + '`\n';
  }

  function generatePropDefaultValue(value) {
    return 'defaultValue: `' + value.value + '`\n';
  }

  function generateProp(propName, prop) {
    return (
      '### `' +
      propName +
      '`' +
      (prop.required ? ' (required)' : '') +
      '\n' +
      '\n' +
      (prop.description ? prop.description + '\n\n' : '') +
      (prop.flowType ? generatePropType(prop.flowType) : '') +
      (prop.defaultValue ? generatePropDefaultValue(prop.defaultValue) : '') +
      '\n'
    );
  }

  function generateProps(props) {
    if (!props) return '\n';
    var title = 'Props';

    return (
      title +
      '\n' +
      stringOfLength('-', title.length) +
      '\n' +
      '\n' +
      Object.keys(props)
        .sort()
        .map(function(propName) {
          return generateProp(propName, props[propName]);
        })
        .join('\n')
    );
  }

  function generateMarkdown(name, reactAPI) {
    var markdownString =
      generateTitle(name) +
      '\n' +
      generateDesciption(reactAPI.description) +
      '\n' +
      generateProps(reactAPI.props);

    return markdownString;
  }

  module.exports = generateMarkdown;

const router = require('express').Router();
let User = require('../models/user.model');
const bcrypt = require('bcrypt');

router.route('/').get(function (req, res) {
    User.find()
        .then(users => res.json(users))
        .catch(err => res.status(400).json('Error: ' + err));
});

async function createUser(username, email, password) {
  const salt = await bcrypt.genSalt();
  const hashedPassword = await bcrypt.hash(password, salt);
  user_detail = {
      "username": username,
      "email": email,
      "password": hashedPassword,
      "salt": salt
  }
  return new User(user_detail);
}


router.route('/users/create').post(async function (req, res) {
  let body = req.body;  
  if (!(body.username && body.email && body.password && validateEmail(body.email))) {
    res.status(400).json("invalid details")
  }

  try {
    (await createUser(req.body.username, req.body.email, req.body.password)).save()
    .then(() => res.json('User added!'))
  }
  catch {
      res.status(500).send();
  }
});

// Login route
router.post('/users/login', async function (req, res) {
    try {
      const user = await User.findOne({ username: req.body.username });
      if (user) {
        const isPasswordValid = await bcrypt.compare(req.body.password, user.password);
        if (isPasswordValid) {
          // Store user details in the session
          req.session.user = {
            id: user._id,
            username: user.username,
            // Add other relevant user details to store in the session if needed.
          };
          res.status(200).json({ message: 'Login successful' });
        } else {
          res.status(401).json({ message: 'Invalid credentials' });
        }
      } else {
        res.status(401).json({ message: 'Invalid credentials' });
      }
    } catch (err) {
      console.error(err);
      res.status(500).json({ message: 'Internal server error' });
    }
  });

// Logout route
router.post('/users/logout', function (req, res) {
    // Destroy the session to log out the user
    req.session.destroy((err) => {
      if (err) {
        console.error('Error destroying session:', err);
        res.status(500).json({ message: 'Server error' });
      } else {
        res.json({ message: 'Logged out successfully' });
      }
    });
  });

  module.exports = {
    createUser: createUser,
    router: router
  };


  // Composed with basic coding tools
  function validateEmail(email) {
    // Regular expression for a valid email address
    const emailRegex = /^[A-Za-z0-9._%-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,4}$/;

    // Test the provided email against the regex pattern
    return emailRegex.test(email);
  }

