    var f_error = null;
    var f_warning = null;
    var f_info = null;
    var f_debug = null;

    function set_log_functions(f_error_, f_warning_, f_info_, f_debug_)
    {
        if(f_error_) {
            f_error = f_error_;
        }
        if(f_warning_) {
            f_warning = f_warning_;
        }
        if(f_info_) {
            f_info = f_info_;
        }
