							Guides
						</a>
						<a href={this.docUrl("tutorials.html", this.props.language)}>
							Tutorials
						</a>
					</div>
					{/* <div>
            <h5>Community</h5>
            <a href={this.pageUrl('users.html', this.props.language)}>
              User Showcase
            </a>
            <a
              href="http://stackoverflow.com/questions/tagged/"
